function stipendLabel(min, max) {
  if (min == null && max == null) return '—';
  const minNum = min != null ? Number(min) : null;
  const maxNum = max != null ? Number(max) : null;
  if (minNum != null && maxNum != null && minNum === maxNum) {
    return `${formatCurrency(minNum)}/mo`;
  }
  if (minNum != null && maxNum != null) {
    return `${formatCurrency(minNum)} – ${formatCurrency(maxNum)}/mo`;
  }
  if (minNum != null) return `${formatCurrency(minNum)}/mo`;
  if (maxNum != null) return `${formatCurrency(maxNum)}/mo`;
  return '—';
}
